public class InnerSecurityConfigurationAtRestEncryptionConfigurationFactory(Action<Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration>
{

    internal InnerSecurityConfigurationLocalDiskEncryptionConfigurationFactory LocalDiskEncryptionConfigurationFactory { get; set; }

    internal InnerSecurityConfigurationS3EncryptionConfigurationFactory S3EncryptionConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration Create()
    {
        var atRestEncryptionConfigurationResult = CreateAtRestEncryptionConfiguration();
        factoryAction?.Invoke(atRestEncryptionConfigurationResult);

        return atRestEncryptionConfigurationResult;
    }

    private Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration CreateAtRestEncryptionConfiguration()
    {
        var atRestEncryptionConfigurationResult = new Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration();

        return atRestEncryptionConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.SecurityConfigurationTypes.AtRestEncryptionConfiguration result)
    {
        base.CreateChildren(result);

        result.LocalDiskEncryptionConfiguration ??= LocalDiskEncryptionConfigurationFactory?.Build();
        result.S3EncryptionConfiguration ??= S3EncryptionConfigurationFactory?.Build();
    }

} // End Of Class

